      if (last >= 0 && segs[last] !== segs[k]) last = -1
      prev[k] = last
      if (types[k] !== T) last = k
    }
    for (let k = n - 1, last = -1; k >= 0; k--) {
      if (last >= 0 && segs[last] !== segs[k]) last = -1
      next[k] = last
